import java.util.*;
import java.io.*;

public class Main {
    static final int MAX = 505;
    static int n, m, mod;
    static int[] fact = new int[MAX * 4];
    static int[] inv_fact = new int[MAX * 4];
    static List<Integer> poly_f = new ArrayList<>();
    static List<Integer> g_poly = new ArrayList<>();

    static int normalize(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void combine(int[] x, int y) {
        x[0] = normalize(x[0] + y);
    }

    static int fast_pow(int base, int exp) {
        int result = 1;
        int b = base;
        int e = exp;
        while (e != 0) {
            if ((e & 1) != 0) result = (int) ((long) result * b % mod);
            b = (int) ((long) b * b % mod);
            e >>= 1;
        }
        return result;
    }

    static void prepare(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }
        inv_fact[n] = fast_pow(fact[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_fact[i] = (int) ((long) inv_fact[i + 1] * (i + 1) % mod);
        }
    }

    static int choose(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (int) ((long) fact[n] * inv_fact[n - m] % mod * inv_fact[m] % mod);
    }

    static int sum_series(int x) {
        return x * (x + 1) / 2;
    }

    static List<Integer> multiply_poly(List<Integer> A, List<Integer> B) {
        int sizeA = A.size();
        int sizeB = B.size();
        List<Integer> C = new ArrayList<>(Collections.nCopies(sizeA + sizeB - 1, 0));
        for (int i = 0; i < sizeA; i++) {
            for (int j = 0; j < sizeB; j++) {
                int val = (int) ((long) A.get(i) * B.get(j) % mod);
                int[] cVal = new int[]{C.get(i + j)};
                combine(cVal, val);
                C.set(i + j, cVal[0]);
            }
        }
        return C;
    }

    static int comb_series(int n, int m) {
        return choose(n + m - 1, n - 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        m = Integer.parseInt(st.nextToken());
        n = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        prepare(m << 1);

        poly_f = new ArrayList<>(Collections.nCopies(n + 1, 0));
        g_poly = new ArrayList<>(Collections.nCopies(n + 1, 0));

        poly_f.set(0, 1);
        for (int i = 1; i <= n; i++) {
            int[] sum = new int[]{0};
            for (int j = 0; j < i; j++) {
                int val = (int) ((long) poly_f.get(j) * poly_f.get(i - 1 - j) % mod);
                val = (int) ((long) val * choose(i - 1, j) % mod);
                combine(sum, val);
            }
            int newVal = (int) ((long) poly_f.get(i) * (i + 1) % mod);
            poly_f.set(i, newVal);
        }

        for (int i = 1; i <= n; i++) {
            int sum_series_j = sum_series(i - 1);
            int sum_series_jj = sum_series(i - 1);
            int[] sum = new int[]{0};
            for (int j = 0; j < i; j++) {
                int term1 = (2L * poly_f.get(j) * g_poly.get(i - 1 - j) % mod);
                term1 = (int) (term1 * choose(i - 1, j) % mod);
                term1 = (int) ((long) term1 * (i + 1) % mod);

                int term2 = (int) ((long) choose(i - 1, j) * (sum_series_j + sum_series_jj) % mod);
                term2 = (int) ((long) term2 * poly_f.get(j) % mod);
                term2 = (int) ((long) term2 * poly_f.get(i - 1 - j) % mod);

                int total = (term1 + term2) % mod;
                combine(sum, total);
            }
            g_poly.set(i, sum[0]);
        }

        g_poly.set(0, 0);
        for (int i = 0; i <= n; i++) {
            g_poly.set(i, (int) ((long) g_poly.get(i) * inv_fact[i] % mod));
            poly_f.set(i, (int) ((long) poly_f.get(i) * inv_fact[i] % mod));
        }

        int answer = 0;
        for (int i = 1; i <= m - n + 1; i++) {
            int val = (int) ((long) g_poly.get(n) * comb_series(i + 1, m - n - i + 1) % mod);
            val = (int) ((long) val * fact[n] % mod);
            val = (int) ((long) val * i % mod);
            answer = (answer + val) % mod;

            g_poly = multiply_poly(g_poly, poly_f);
            if (g_poly.size() > n + 1) {
                g_poly = g_poly.subList(0, n + 1);
            }
        }

        System.out.println(answer);
    }
}
